package com.personal.jobagent.discovery;
import com.fasterxml.jackson.databind.ObjectMapper; import io.micrometer.core.instrument.MeterRegistry; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import java.sql.Timestamp; import java.util.*;
@Service public class DiscoveryTelemetry {private final JdbcTemplate db;private final MeterRegistry metrics;private final ObjectMapper json;public DiscoveryTelemetry(JdbcTemplate d,MeterRegistry m,ObjectMapper j){db=d;metrics=m;json=j;}public void record(ScraperProvider.ExtractionResult r){record(r,Map.of());} public void record(ScraperProvider.ExtractionResult r,Map<String,Object> comparison){try{String body=json.writeValueAsString(Map.of("jobCount",r.jobs().size(),"successful",r.successful()));String compare=json.writeValueAsString(comparison);db.update("insert into discovery_extractions(id,correlation_id,provider,started_at,completed_at,result,confidence,error,retry_count,comparison_result) values(?,?,?,?,?,?::jsonb,?,?,?,?::jsonb)",UUID.randomUUID(),r.correlationId(),r.provider(),Timestamp.from(r.startedAt()),Timestamp.from(r.completedAt()),body,r.confidence(),r.error(),r.retryCount(),compare);}catch(Exception ignored){}metrics.counter("scrape_attempts_total","provider",r.provider()).increment();metrics.counter(r.successful()?"scrape_success_total":"scrape_failure_total","provider",r.provider()).increment();}}
